{"args": ["-c", "import re
D=re.compile(r'(?<![0-9A-Za-z])([0-9]{4})-([0-9]{2})-([0-9]{2})(?![0-9A-Za-z])')
DIM={1:31,2:29,3:31,4:30,5:31,6:30,7:31,8:31,9:30,10:31,11:30,12:31}
for i,l in enumerate(open('log.txt',encoding='utf-8').read().splitlines(),1):
    out=[]
    for m in D.finditer(l):
        mo,d=int(m.group(2)),int(m.group(3))
        out.append((m.group(0), 1<=mo<=12 and 1<=d<=DIM[mo]))
    print(i,out)"], "command": "C:/ProgramData/anaconda3/python.exe"}

